POS = re.compile(r'(' + NAMES + r'):(\d+):(\d+)(?:-(\d+)(?::(\d+))?)?') if EDITED else None
DOTPOS = re.compile(r'(' + NAMES + r'):(\d+)\.(\d+)') if EDITED else None     # the Block at file:L.C form


def remap(s):
